# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, K, Y, P, C = "Lucas", "Min-seo", "Yu-na", "Park", "Soo-jin"
D = [
("#", "Escena 1 · 11:00 · Showroom de Seorin, Gangnam", "장면 1 · 오전 11시 · 강남, 서린 쇼룸"),
(None, "Jueves 2 de abril. Una planta baja con escaparates enormes a una avenida llena de tráfico. Dentro, luz cálida y suelos de muestra de seis marcas distintas. En el centro, sobre una tarima, las cuatro piezas de ochenta por ciento sesenta, colocadas como dijo Nuria: una normal, otra girada. Al lado, un cartel provisional: «Blanco Hangang».", "4월 2일 목요일. 차로 가득한 대로를 향해 커다란 쇼윈도가 난 1층 공간. 안은 따뜻한 조명에, 여섯 개 브랜드의 샘플 바닥이 깔려 있다. 가운데 단 위에는 80×160 네 장이 누리아가 말한 대로 깔려 있다. 한 장은 그대로, 한 장은 돌려서. 옆에는 임시 안내판. '블랑코 한강.'"),
(Y, "(desde una escalera, colgando el cartel) ¿Está recto? Dime la verdad.", "(사다리 위에서 안내판을 걸며) 똑바로예요? 솔직하게 말해 줘요."),
(L, "Un poco a la izquierda. Un poquito más. Ahí. Perfecto.", "왼쪽으로 조금만. 조금 더. 거기요. 완벽해요."),
(Y, "Si el director Park ve un cartel torcido, me manda a Busan a vender azulejos con el padre de la daepyo-nim.", "박 상무님이 비뚤어진 안내판을 보면 저를 부산으로 보내서 대표님 아버님이랑 타일 팔게 할 거예요."),
(L, "Hablando del padre de la señora Kim: hay que hacerle la foto del catálogo. Se lo prometí anoche.", "김 대표님 아버님 얘기가 나와서 말인데, 카탈로그 사진 찍어 드려야 해요. 어젯밤에 약속했거든요."),
(Y, "¡Ya lo sé! Lo tengo apuntado: «Foto para el señor Kim, Busan, después de la presentación, con rana». No sé qué significa lo de la rana, pero lo he apuntado.", "알아요! 적어 놨어요. '부산 김 사장님께 보낼 사진, 발표 후, 개구리 포함.' 개구리가 뭔지는 모르겠지만 적어 놨어요."),
(None, "Kim Min-seo entra con una carpeta y recorre el showroom en silencio. Se detiene, se agacha, pasa la mano por una de las piezas y mira la luz reflejada desde muy cerca.", "김민서가 서류철을 들고 들어와 말없이 쇼룸을 한 바퀴 돈다. 멈춰 서서 쪼그려 앉아 타일 한 장을 손으로 쓸어 보고, 아주 가까이서 반사된 빛을 본다."),
(K, "Hay una huella aquí. Una huella de dedo, en la esquina.", "여기 자국이 있어요. 모서리에 손가락 자국이요."),
(L, "(se acerca) Ni la había visto.", "(다가가며) 전혀 못 봤어요."),
(K, "Los arquitectos se agachan igual que yo. Yu-na, el paño de microfibra, por favor.", "건축가들도 저처럼 쪼그려 앉아요. 유나 씨, 극세사 천 좀 주세요."),
(Y, "(baja de la escalera) ¡Al tiro! Así dice el director Park cuando quiere algo ya. Lo aprendió en Chile.", "(사다리에서 내려오며) '알 티로!' 박 상무님이 뭔가를 당장 원할 때 그렇게 말해요. 칠레에서 배우셨대요."),
(L, "¿«Al tiro»? En España diríamos «ahora mismo».", "'알 티로'요? 스페인에선 '지금 당장'이라고 하죠."),
(K, "Y en México, «ahorita», que puede ser dentro de una semana. El director Park pasó cinco años en una obra de Hanul en Santiago de Chile. Habla español como allí: rápido, con «po» al final de las frases.", "멕시코에선 '아오리타'인데, 일주일 뒤일 수도 있죠. 박 상무님은 칠레 산티아고의 한울 현장에서 5년을 보내셨어요. 거기 사람들처럼 스페인어를 해요. 빠르게, 문장 끝에 '포'를 붙여서요."),
(L, "¿«Po»?", "'포'요?"),
(K, "Viene de «pues». «Sí, po», «ya, po». Si le dice «ya, po», es buena señal. Si le dice «ya» a secas, también. Si no dice nada, preocúpese.", "'푸에스'에서 왔어요. '시 포', '야 포.' '야 포'라고 하면 좋은 신호예요. 그냥 '야'라고만 해도 괜찮아요. 아무 말도 안 하면, 그땐 걱정하세요."),
(L, "Silencio, preocupación. Entendido. ¿Algo más que deba saber?", "침묵이면 걱정. 알겠어요. 제가 알아야 할 게 더 있나요?"),
(K, "Que no le gusta que le lean las diapositivas. Ya las ha visto. Le he enviado el documento esta mañana.", "슬라이드를 읽어 주는 걸 싫어하세요. 이미 보셨어요. 오늘 아침에 자료를 보내 드렸거든요."),
(L, "¿Ya las ha visto? Entonces, ¿qué hago durante veinte minutos?", "벌써 보셨다고요? 그럼 저는 20분 동안 뭘 하죠?"),
(K, "Contar lo que no está en las diapositivas. Lo que vio usted en Riad, en Monterrey. Lo que dijo ayer: «En Corea el suelo se vive».", "슬라이드에 없는 걸 이야기하세요. 리야드에서, 몬테레이에서 직접 보신 것. 어제 하신 말. '한국에선 바닥에서 산다.'"),
(L, "Esa frase era suya.", "그건 대표님 말이었잖아요."),
(K, "Ayer era mía. Hoy es de usted. Así funcionan los buenos socios.", "어제는 제 거였죠. 오늘은 페레르 씨 거예요. 좋은 파트너는 그렇게 하는 거예요."),
(L, "¿Y qué hago con los nervios?", "그럼 긴장은 어떻게 하죠?"),
(K, "Lo mismo que yo: revisar la lista por tercera vez.", "저처럼 하세요. 목록을 세 번째로 다시 보는 거예요."),
(Y, "Y comer algo. La daepyo-nim nunca come antes de una presentación y luego le duele la cabeza.", "그리고 뭐라도 드세요. 대표님은 발표 전엔 절대 안 드셔서 나중에 머리가 아프세요."),
(K, "Yu-na.", "유나 씨."),
(Y, "Perdón, daepyo-nim. (a Lucas, en voz baja) Pero es verdad.", "죄송해요, 대표님. (루카스에게 작은 소리로) 근데 사실이에요."),
(L, "Pues compro tres kimbaps. Uno para cada uno.", "그럼 김밥 세 줄 살게요. 한 사람에 하나씩."),

("#", "Escena 2 · 13:40 · Entrada del showroom — llega el director Park", "장면 2 · 오후 1시 40분 · 쇼룸 입구 — 박 상무 도착"),
(None, "Un coche negro se detiene delante del escaparate. Baja un hombre de cincuenta y dos años, traje azul oscuro, gafas de montura fina. Le acompañan una arquitecta joven y dos empleados con carpetas. Min-seo y Yu-na se inclinan. Lucas las imita, un segundo tarde.", "검은 차가 쇼윈도 앞에 선다. 짙은 남색 정장에 가는 테 안경을 쓴 쉰두 살의 남자가 내린다. 젊은 여성 건축가와 서류철을 든 직원 두 명이 함께 온다. 김민서와 유나가 고개를 숙이고, 루카스는 1초 늦게 따라 한다."),
(P, "Buenas tardes. Park Jun-ho, de Hanul. (le ofrece la tarjeta con las dos manos)", "안녕하세요. 한울의 박준호입니다. (두 손으로 명함을 내밀며)"),
(L, "(la recibe con las dos manos, la lee) Encantado, director Park. Lucas Ferrer, de Cerámicas Albalat. (le da la suya)", "(두 손으로 받아 읽으며) 반갑습니다, 박 상무님. 세라미카스 알발라트의 루카스 페레르입니다. (자기 명함을 건넨다)"),
(P, "(mira la tarjeta) «Responsable de Expansión Internacional». ¿Hace cuánto?", "(명함을 보며) '해외사업 책임자'. 얼마나 되셨어요?"),
(L, "Catorce meses.", "14개월이요."),
(P, "Catorce meses. Y ya cuatro países. Harto rápido, ¿no?", "14개월. 그런데 벌써 4개국. 엄청 빠르네요, 그렇죠?"),
(L, "Más rápido de lo que habríamos querido, a veces. Pero cada país lo hemos ganado con una fábrica detrás.", "가끔은 저희가 원한 것보다 빨랐습니다. 하지만 나라마다 뒤에 공장이 있었기에 따낸 겁니다."),
(P, "Ya. (pausa) Le presento a la arquitecta Choi Soo-jin, jefa de diseño interior de Lumière. Estudió en Barcelona.", "음. (잠시 멈추며) 뤼미에르 실내디자인 팀장 최수진 건축가를 소개합니다. 바르셀로나에서 공부했어요."),
(C, "Encantada. Cuatro años en la Escuela de Arquitectura. Todavía sueño con el mosaico del Park Güell.", "반갑습니다. 건축학교에서 4년 있었어요. 아직도 구엘 공원 모자이크가 꿈에 나와요."),
(L, "Entonces sabe usted más de cerámica española que muchos españoles.", "그럼 웬만한 스페인 사람보다 스페인 도자기를 더 잘 아시겠네요."),
(C, "Sé de mosaicos rotos. De porcelánico de ochenta por ciento sesenta, todavía no.", "깨진 모자이크는 알죠. 80×160 자기질 타일은 아직 모르고요."),
(P, "Por eso vinimos. ¿Usted ha estado en Chile, señor Ferrer?", "그래서 왔습니다. 페레르 씨는 칠레에 가 보셨어요?"),
(L, "Todavía no. México, Colombia, Estados Unidos, Arabia Saudí... Chile está en la lista.", "아직요. 멕시코, 콜롬비아, 미국, 사우디아라비아… 칠레는 목록에 있습니다."),
(P, "Cinco años estuve en Santiago. Un hospital de veinte pisos. Ahí aprendí dos cosas: español chileno y que los terremotos no perdonan una junta mal hecha. ¿Cachai?", "산티아고에서 5년 있었어요. 20층짜리 병원이었죠. 거기서 두 가지를 배웠어요. 칠레 스페인어, 그리고 지진은 잘못 만든 줄눈을 봐주지 않는다는 거. 무슨 말인지 알죠?"),
(L, "«¿Cachai?»... ¿Si lo entiendo?", "'카차이?'… 이해했냐는 뜻인가요?"),
(P, "Eso. «¿Entiende?», en chileno. Vamos bien.", "그거요. 칠레식 '이해하세요?'예요. 잘하고 있네요."),
(C, "Señor Ferrer, ¿puedo pisar las piezas? En Corea, si no lo pisamos, no lo creemos.", "페레르 씨, 타일을 밟아 봐도 될까요? 한국에선 밟아 보지 않으면 안 믿어요."),
(L, "Por favor. Con zapatos o sin zapatos, como prefiera.", "물론이죠. 신발을 신든 벗든 편하신 대로요."),
(C, "Sin zapatos, y después. Primero quiero escuchar.", "벗고, 나중에요. 먼저 들어 보고 싶어요."),
(P, "Soo-jin siempre pisa primero y pregunta después. Hoy ha cambiado el orden. Buena señal.", "수진 씨는 늘 먼저 밟고 나중에 물어요. 오늘은 순서를 바꿨네요. 좋은 신호예요."),
(K, "Director Park, si le parece, empezamos a las dos en punto.", "상무님, 괜찮으시면 2시 정각에 시작하겠습니다."),
(P, "A las dos en punto. Ya, po.", "2시 정각. 좋아요."),
(None, "Yu-na mira a Lucas y levanta un pulgar, muy discretamente.", "유나가 루카스를 보며 아주 조심스럽게 엄지를 든다."),

("#", "Escena 3 · 14:00 · La presentación", "장면 3 · 오후 2시 · 발표"),
(None, "Doce arquitectos de Hanul sentados en semicírculo. El director Park, en el centro, con los brazos cruzados. Kim Min-seo presenta en coreano y luego cede la palabra. Lucas no enciende el proyector.", "한울 건축가 열두 명이 반원으로 앉아 있다. 가운데에 박 상무가 팔짱을 끼고 앉아 있다. 김민서가 한국어로 소개를 한 뒤 발언권을 넘긴다. 루카스는 프로젝터를 켜지 않는다."),
(L, "Buenas tardes. Gracias por recibirme. Las diapositivas ya las tienen, así que no se las voy a leer. En primer lugar, quiero contarles algo que he aprendido en Seúl en dos días.", "안녕하세요. 맞아 주셔서 감사합니다. 슬라이드는 이미 갖고 계시니 읽어 드리지 않겠습니다. 먼저 이틀 동안 서울에서 배운 걸 말씀드리고 싶습니다."),
(None, "Min-seo traduce al coreano, frase por frase. Algunos arquitectos levantan la vista del móvil.", "김민서가 한 문장씩 한국어로 통역한다. 몇몇 건축가가 휴대폰에서 눈을 든다."),
(P, "(en español, sin descruzar los brazos) Adelante. Sin diapositivas, mejor.", "(팔짱을 낀 채 스페인어로) 계속하세요. 슬라이드 없는 게 낫네요."),
(L, "En Europa, el suelo se pisa. En Corea, el suelo se vive. Aquí se camina descalzo, se come, se duerme sobre él. Y en invierno está tibio. Así que una baldosa coreana no es una baldosa europea: es una baldosa que trabaja todos los días.", "유럽에서는 바닥을 밟습니다. 한국에서는 바닥에서 삽니다. 여기선 맨발로 걷고, 그 위에서 먹고, 잡니다. 그리고 겨울엔 따뜻하죠. 그러니 한국의 타일은 유럽의 타일이 아닙니다. 매일 일하는 타일입니다."),
(C, "(en español, desde su asiento) ¿Y cómo sabe que su baldosa aguanta ese trabajo?", "(자리에서 스페인어로) 그 타일이 그 일을 견딘다는 건 어떻게 아세요?"),
(L, "Es justo lo que quería contarles a continuación. Fíjense en esta foto. (enciende el proyector, diapositiva cuatro) Es una obra de Riad, en diciembre.", "바로 그다음에 말씀드리려던 겁니다. 이 사진을 봐 주세요. (프로젝터를 켜고 4번 슬라이드를 띄운다) 12월, 리야드의 현장입니다."),
(C, "¿En pleno desierto?", "사막 한가운데서요?"),
(L, "Calentamos la superficie a cincuenta grados durante cuatro horas y luego la mojamos con agua fría. Tres veces. Ocho piezas de gran formato. Pasaron las ocho.", "표면을 50도로 네 시간 데운 다음 찬물을 부었습니다. 세 번이요. 대형 타일 여덟 장. 여덟 장 모두 통과했습니다."),
(C, "¿Las ocho a la primera?", "여덟 장 다 한 번에요?"),
(L, "No. En el primer ciclo se levantó la de la esquina. Como pueden ver en esta otra foto, la pieza estaba intacta. El fallo era la colocación: sin junta perimetral y con el adhesivo a pegotes. La volvimos a colocar bien y aguantó.", "아니요. 첫 회차에 모서리 판이 들떴습니다. 이 사진에서 보시듯 타일 자체는 멀쩡했습니다. 문제는 시공이었어요. 테두리 줄눈이 없었고, 접착제를 덩어리로 발랐죠. 제대로 다시 깔았더니 견뎠습니다."),
(P, "(descruza los brazos) ¿Eso está en el informe?", "(팔짱을 풀며) 그게 보고서에 있어요?"),
(L, "Está en el informe, firmado por la inspectora saudí, con el fallo incluido. No lo hemos quitado.", "보고서에 있습니다. 사우디 검사관이 서명했고, 실패한 부분까지 포함돼 있습니다. 빼지 않았습니다."),
(P, "¿Por qué no lo quitaron? Habría quedado mejor.", "왜 안 뺐어요? 그게 더 보기 좋았을 텐데."),
(L, "Porque fue en ese fallo donde aprendimos lo más importante: el problema casi nunca es la pieza, sino la colocación. Por eso, si trabajamos juntos, nuestro técnico formará a sus colocadores antes del primer piso.", "그 실패에서 가장 중요한 걸 배웠기 때문입니다. 문제는 거의 늘 타일이 아니라 시공이라는 걸요. 그래서 함께 일하게 되면, 첫 세대를 깔기 전에 저희 기술자가 시공팀을 교육할 겁니다."),
(P, "¿Qué técnico?", "어떤 기술자요?"),
(L, "Pepe Llorens. Cuarenta años en nuestra fábrica. Ahora mismo está en Riad formando a los equipos de la obra.", "페페 요렌스입니다. 저희 공장에서 40년을 일했습니다. 지금은 리야드에서 현장 시공팀을 교육하고 있습니다."),
(Y, "(en voz baja, a Min-seo) El del bigote.", "(김민서에게 작은 소리로) 콧수염 그분이요."),
(P, "Ya. Siguiente pregunta: el plazo. Lumière son tres complejos. El primero empieza a recibir suelo en septiembre.", "음. 다음 질문. 납기요. 뤼미에르는 단지가 세 곳이에요. 첫 단지가 9월부터 바닥재를 받기 시작합니다."),
(L, "El cuatro de mayo encendemos un horno que hemos reformado para estos formatos. Desde junio, cualquier pedido confirmado antes del quince de mayo puede estar en Busan en septiembre.", "5월 4일에 이 규격용으로 개보수한 가마에 불을 붙입니다. 6월부터는 5월 15일 전에 확정된 주문이라면 어떤 것이든 9월에 부산에 도착할 수 있습니다."),
(P, "¿«Puede estar» o «estará»?", "'도착할 수 있다'예요, '도착한다'예요?"),
(L, "(pausa) «Estará», si el pedido se confirma antes del quince de mayo. Si se confirma después, no se lo prometo hoy: se lo confirmo por escrito.", "(잠시 멈추며) 5월 15일 전에 확정되면 '도착합니다'. 그 뒤에 확정되면 오늘 약속하지 않겠습니다. 서면으로 확인해 드리겠습니다."),
(P, "Ya, po.", "좋아요."),
(C, "Pregunta de diseño: el tono. Tres complejos, dos años. ¿El blanco del tercer complejo será igual que el del primero?", "디자인 질문이요. 색조요. 단지 세 곳, 2년. 세 번째 단지의 흰색이 첫 번째와 같을까요?"),
(L, "Será igual dentro de cada complejo, porque cada complejo se fabricará con un solo lote. Entre complejos puede haber una pequeña diferencia, y por eso les proponemos guardar un uno por ciento de cada lote para reposiciones.", "단지 안에서는 같습니다. 단지마다 한 로트로만 생산하니까요. 단지 사이에는 작은 차이가 있을 수 있어서, 보수용으로 로트마다 1%를 보관하자고 제안드립니다."),
(C, "Eso es honesto.", "솔직하시네요."),
(L, "Lo aprendimos hace años en España, con un cliente que mezcló dos lotes en el mismo edificio. Una vez es suficiente.", "몇 년 전 스페인에서 배웠습니다. 한 고객이 같은 건물에 두 로트를 섞었거든요. 한 번이면 충분하죠."),
(C, "Una pregunta más, de baño. ¿El semipulido resbala con los pies mojados?", "욕실 질문 하나 더요. 반광은 젖은 발로 밟으면 미끄러워요?"),
(L, "En seco, no. Mojado, un poco más. Por eso para baños proponemos el acabado mate, que en Miami pasó la prueba de resbalamiento. El semipulido, para salones y paredes.", "마른 상태에선 아니요. 젖으면 조금 더 미끄럽습니다. 그래서 욕실엔 마이애미에서 미끄럼 시험을 통과한 무광 마감을 제안드립니다. 반광은 거실과 벽에요."),
(C, "Brillo en el salón, seguridad en el baño.", "거실엔 광택, 욕실엔 안전."),
(L, "En Miami lo decíamos así: «Brillo arriba, seguridad abajo».", "마이애미에선 이렇게 말했어요. '광택은 위에, 안전은 아래에.'"),
(P, "Me gusta. Corto. Se entiende.", "마음에 드네요. 짧고. 이해되고."),
(C, "Lo pondré en la memoria de diseño.", "설계 설명서에 넣을게요."),
(P, "Roturas.", "파손."),
(L, "Menos del uno por ciento en nuestros últimos tres destinos, con cantoneras en cada caja y separadores entre piezas. Mañana su equipo de calidad lo podrá comprobar con sus propias manos.", "최근 세 곳에서 1% 미만입니다. 상자마다 모서리 보호대, 타일 사이엔 간지를 넣습니다. 내일 품질팀이 직접 손으로 확인하실 수 있습니다."),
(P, "Precio.", "가격."),
(L, "El precio se lo doy mañana, después de que su equipo abra las cajas, y por escrito, con los tres complejos por separado. No quiero darle hoy un número a medias.", "가격은 내일 품질팀이 상자를 열어 본 뒤에, 단지 세 곳을 따로 나눠 서면으로 드리겠습니다. 오늘 반쪽짜리 숫자를 드리고 싶지 않습니다."),
(P, "(mira a Min-seo) No ha dicho «quizás» ni una vez.", "(김민서를 보며) '아마도'라는 말을 한 번도 안 했네요."),
(K, "Le advertí, director Park.", "미리 말씀드렸습니다, 상무님."),
(P, "(casi sonríe) Ya me di cuenta.", "(거의 미소 지으며) 알아챘어요."),
(L, "Para terminar, una cosa sobre el nombre. «Blanco Hangang» es un nombre de trabajo. Lo hemos elegido porque nuestra colección tiene hermanos con nombre de ciudad: Monterrey tiene «Blanco San Pedro»; Miami, «Blanco Biscayne». Si Hanul prefiere otro, cualquier nombre que elijan será bienvenido.", "마지막으로 이름에 관해 한 가지. '블랑코 한강'은 가제입니다. 저희 컬렉션에는 도시 이름을 단 형제들이 있어서 이렇게 지었습니다. 몬테레이엔 '블랑코 산페드로', 마이애미엔 '블랑코 비스케인'. 한울이 다른 이름을 원하시면 어떤 이름이든 환영입니다."),
(C, "A mí me gusta. Hangang es el centro de Seúl. Todo el mundo tiene un recuerdo del río.", "저는 좋아요. 한강은 서울의 중심이잖아요. 누구나 강에 대한 추억이 있어요."),
(L, "Entonces, muchas gracias por su tiempo. Quedo a su disposición para cualquier pregunta.", "그럼 시간 내 주셔서 정말 감사합니다. 어떤 질문이든 답해 드리겠습니다."),

("#", "Escena 4 · 15:40 · Junto a la tarima — la pregunta diecisiete", "장면 4 · 오후 3시 40분 · 단 옆 — 17번 질문"),
(None, "Los arquitectos se han acercado a las piezas. Algunos se agachan y pasan la mano, igual que Min-seo por la mañana. Dos se quitan los zapatos y caminan en calcetines sobre la tarima. El director Park se queda de pie, frente a Lucas.", "건축가들이 타일 쪽으로 다가와 있다. 몇몇은 아침의 김민서처럼 쪼그려 앉아 손으로 쓸어 본다. 두 명은 신발을 벗고 양말 바람으로 단 위를 걷는다. 박 상무는 루카스 앞에 선 채로 있다."),
(P, "Señor Ferrer. Una última pregunta. Sin diapositivas.", "페레르 씨. 마지막 질문 하나요. 슬라이드 없이."),
(L, "Por supuesto.", "물론이죠."),
(P, "¿Por qué deberíamos confiar en una fábrica que hace dos años solo vendía en España?", "2년 전만 해도 스페인에서만 팔던 공장을 왜 믿어야 합니까?"),
(None, "Min-seo, a dos metros, no se mueve. Yu-na deja de respirar.", "2미터 떨어진 곳의 김민서는 미동도 없다. 유나는 숨을 멈춘다."),
(L, "Porque no les pido que confíen en nuestra historia. La historia es bonita, pero no se pisa. Les pido que mañana abran las cajas.", "저희 이야기를 믿어 달라고 부탁드리지 않겠습니다. 이야기는 아름답지만 밟을 수는 없으니까요. 내일 상자를 열어 봐 달라는 겁니다."),
(P, "¿Y si las cajas fallan?", "상자가 불합격이면요?"),
(L, "Entonces sabrá usted algo que nosotros necesitamos saber. Y yo se lo diré a mi fábrica esa misma tarde. Hace dos años solo vendíamos en España, es verdad. Pero fue precisamente por eso por lo que aprendimos a escuchar: en Monterrey, en Miami, en Riad. No llegamos sabiendo. Llegamos preguntando.", "그럼 저희가 꼭 알아야 할 걸 상무님이 알게 되시는 거죠. 저는 그날 오후에 바로 공장에 전하겠습니다. 2년 전엔 스페인에서만 팔았던 게 맞습니다. 하지만 바로 그래서 듣는 법을 배웠습니다. 몬테레이에서, 마이애미에서, 리야드에서. 저희는 다 알고 간 게 아니라 물으면서 갔습니다."),
(P, "(silencio largo) ...", "(긴 침묵) …"),
(L, "(no dice nada)", "(아무 말도 하지 않는다)"),
(P, "Mañana, a las nueve, nuestro equipo de calidad abre las cajas. Pieza por pieza.", "내일 9시, 저희 품질팀이 상자를 엽니다. 한 장 한 장."),
(L, "Allí estaremos a las ocho y media.", "8시 반에 가 있겠습니다."),
(P, "(le da la mano) Ya, po. (a Min-seo, en coreano, algo breve; luego, en español) Ha estado bien.", "(악수를 청하며) 좋아요. (김민서에게 한국어로 짧게 뭔가 말하고, 이어 스페인어로) 괜찮았어요."),
(None, "El director Park y su equipo se marchan. El coche negro se pierde en la avenida. Durante unos segundos, nadie habla.", "박 상무와 일행이 떠난다. 검은 차가 대로 속으로 사라진다. 몇 초 동안 아무도 말하지 않는다."),
(Y, "¿Qué le ha dicho en coreano, daepyo-nim? ¡No lo he oído!", "한국어로 뭐라고 하셨어요, 대표님? 못 들었어요!"),
(K, "Me ha dicho: «No ha dicho “quizás”». Y luego: «Ha estado bien».", "'아마도라는 말을 안 했네요'라고 하셨어요. 그리고 '괜찮았어요'."),
(L, "¿«Ha estado bien» es bueno?", "'괜찮았어요'가 좋은 거예요?"),
(K, "Viniendo del director Park, «ha estado bien» es casi un aplauso. En nueve años, se lo he oído decir dos veces.", "박 상무님 입에서 나온 '괜찮았어요'는 거의 박수예요. 9년 동안 두 번 들었어요."),
(Y, "¡Tres! La primera vez yo no estaba, pero me lo contaron.", "세 번이에요! 첫 번째는 제가 없었지만 들었어요."),
(L, "(se deja caer en una silla) Ha sido la pregunta diecisiete más larga de mi vida.", "(의자에 털썩 앉으며) 인생에서 가장 긴 17번 질문이었어요."),
(K, "Y la ha respondido mejor de lo que yo esperaba. Aunque mañana es lo que de verdad cuenta.", "그리고 제 기대보다 잘 답하셨어요. 하지만 진짜 중요한 건 내일이에요."),
(L, "Anoche escribí cuatro respuestas y las tiré las cuatro. Hoy he dicho lo que me ha salido.", "어젯밤에 답을 네 개 써서 네 개 다 버렸어요. 오늘은 나오는 대로 말했어요."),
(K, "Eso se nota. Las respuestas preparadas suenan a diapositiva.", "티가 났어요. 준비한 답은 슬라이드 같은 소리가 나거든요."),
(L, "Las diapositivas, para la cuatro.", "슬라이드는 4번에만."),
(K, "(sonríe) Para la cuatro.", "(미소 지으며) 4번에만."),
(Y, "Lucas, mañana te recojo a las ocho. Y no olvides la tarjeta del gato.", "루카스, 내일 8시에 데리러 갈게요. 고양이 카드 잊지 말고요."),
(L, "Mañana, las cajas. Esta noche escribo a Onda: quiero saber cómo vienen embaladas exactamente las muestras de catálogo que les mandamos.", "내일은 상자죠. 오늘 밤 온다에 연락할게요. 지난번에 보낸 카탈로그 샘플이 정확히 어떻게 포장돼 왔는지 알아야겠어요."),
(K, "Hágalo. Pero antes... (saca el móvil) nos queda una promesa.", "그렇게 하세요. 그런데 그 전에… (휴대폰을 꺼내며) 약속이 하나 남았죠."),
(Y, "¡La foto para Busan! (coge el catálogo de Albalat y lo abre por la página de Blanco San Pedro) ¿Y la rana? ¿Dónde está la rana?", "부산에 보낼 사진! (알발라트 카탈로그를 집어 블랑코 산페드로 쪽을 펼치며) 그런데 개구리는요? 개구리는 어디 있어요?"),
(L, "(señala la veta de la pieza girada, en la tarima) Ahí. Escondida en la veta. Hay que buscarla.", "(단 위에 돌려 깐 타일의 결을 가리키며) 저기요. 결 속에 숨어 있어요. 찾아봐야 해요."),
(K, "(mira la pieza un buen rato; luego, por primera vez en tres días, se ríe con ganas) Mi padre la va a encontrar antes que yo.", "(한참 타일을 보다가, 사흘 만에 처음으로 크게 웃으며) 아버지가 저보다 먼저 찾으실 거예요."),
(Y, "¡Voy a hacer diez fotos! Una para Busan y otra para Onda.", "사진 열 장 찍을게요! 하나는 부산에, 하나는 온다에."),
(L, "Y una para Amparo. El domingo sale para Riad con su padre.", "그리고 하나는 암파로한테요. 일요일에 아버님이랑 리야드로 떠나요."),
(Y, "¡Hecho! A ver, todos juntos... ¡Kimchi!", "알겠어요! 자, 다 같이… 김치!"),
(K, "(todavía riéndose) En Corea decimos «kimchi» en las fotos, señor Ferrer. Como ustedes dicen «patata».", "(아직 웃으며) 한국에선 사진 찍을 때 '김치'라고 해요, 페레르 씨. 스페인에서 '파타타'라고 하듯이요."),
(L, "Entonces: ¡kimchi!", "그럼… 김치!"),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "4월 2일 목요일, 강남 서린 쇼룸. 발표 세 시간 전, 김민서는 타일 위의 손가락 자국 하나까지 찾아낸다. 오후 1시 40분, 칠레 산티아고 현장에서 5년을 보낸 한울의 박준호 상무가 도착한다. 짧은 칠레식 스페인어를 쓰는 사람이다. 루카스는 슬라이드를 읽지 않고, '한국에선 바닥에서 산다'는 이야기로 발표를 시작한다. 리야드의 실패 사례까지 담긴 보고서, 납기, 색조, 파손, 가격 질문이 이어진 뒤, 박 상무가 마지막으로 17번 질문을 던진다.",
 "듣기 질문 ① 박 상무의 스페인어에는 어떤 칠레식 표현이 나오는가? 김민서는 그의 '야 포'와 침묵을 어떻게 해석하라고 했나?",
 "듣기 질문 ② 루카스는 왜 리야드 보고서에서 실패한 부분을 빼지 않았다고 하는가? 납기 질문에서 '도착할 수 있다'와 '도착한다'의 차이는?",
 "듣기 질문 ③ 17번 질문에 루카스는 어떻게 답하는가? 박 상무가 한국어로 김민서에게 한 말은 무엇이고, 그게 왜 중요한가?",
]),
]

